SourceCode.Declaration:
/// <summary>
/// Batch service class for Post sales order shipment processing
/// </summary>
class METSalesOrderShipmentConfirmationService extends METSysOperationService
{
    private guid topPickingProcessId;
    container    con;
    int          remaningCount;
    List         processShipmentList;

}

Method.Source:
/// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METSalesOrderShipmentConfirmationTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METSalesOrderShipmentConfirmationTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return strFmt("@MET:ShipConfirm" + this.prepareShipmentsForTask());
}

/// <summary>
/// Assign the specific shipments to the batch task
/// </summary>
/// <returns>Description of the batch task</returns>
protected str prepareShipmentsForTask()
{
    METSalesOrderShipmentConfirmationContract   taskDataContract        = dataContract as METSalesOrderShipmentConfirmationContract;
    System.Text.StringBuilder                   caption                 = new System.Text.StringBuilder();
    int                                         shipmentCount           = taskDataContract.parmShipmentIdList().elements() / taskDataContract.parmThreadCount();
    int                                         noOfShipmentsToProcess  = (remaningCount > 0) ? shipmentCount + 1 : shipmentCount;

    processShipmentList = new List(Types::String);

    for (int i = 1; i<= noOfShipmentsToProcess; i++)
    {
        processShipmentList.addEnd(conPeek(con, 1));
        caption.Append(' | ' + conPeek(con, 1));
        con = conDel(con, 1, 1);
    }
    remaningCount -= 1;

    return caption.ToString();
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METSalesOrderShipmentConfirmationContract _contract)
{
    con             = list2Con(_contract.parmShipmentIdList());
    remaningCount   = _contract.parmShipmentIdList().elements() mod _contract.parmThreadCount();

    this.processInternal(_contract);
}

/// <summary>Initialise global variables</summary>
public void initialise()
{
    super();  

    METSalesOrderShipmentConfirmationContract contract = dataContract as METSalesOrderShipmentConfirmationContract;
    this.processShipmentConfirmation(contract);
}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METSalesOrderShipmentConfirmationContract contract = _taskDataContract as METSalesOrderShipmentConfirmationContract;
    contract.parmShipmentIdList(processShipmentList);
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METSalesOrderShipmentConfirmationContract();
}

/// <summary>
/// Process sales orders to substitute from the query and insert SO number in <c>METPostSalesOrderCreationProcessingQueue</c>
/// </summary>
/// <param name = "_contract">Contract class reference</param>
void processShipmentConfirmation(METSalesOrderShipmentConfirmationContract  _contract)
{
    List                shipmentIdList = _contract.parmShipmentIdList();
    ListEnumerator      enumerator = shipmentIdList.getEnumerator();
    RecordInsertList    shipmentConfirmationRecordList;
    METSalesOrderShipmentConfirmationQueue  postQueue;
    WHSParameters whsParameters = WHSParameters::find();
    METSalesOrderShipmentLoadLines metSalesOrderShipmentLoadLines;
    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;
    METCustTable metCustTable;
    boolean             shipmentLevelExecution = false;
    boolean             TMSTask = _contract.parmTMS();
    #OCCRetryCount

    METSalesOrderShipmentConfirmationQueue::cleanUpPostSalesOrderCreationProcessingQueue();
    shipmentConfirmationRecordList = new RecordInsertList(tableNum(METSalesOrderShipmentConfirmationQueue));
    topPickingProcessId = newGuid();

    if (whsParameters.METShipmentConfirmationBatchGroupId)
    {
        batchHeader.parmBatchGroup(whsParameters.METShipmentConfirmationBatchGroupId);
    }

    while(enumerator.moveNext())
    {
        metSalesOrderShipmentLoadHeader = METSalesOrderShipmentLoadHeader::findByShipmentId(enumerator.current());
        metCustTable = METCustTable::find(metSalesOrderShipmentLoadHeader.CustAccount);

        try
        {
            ttsbegin;

            if (!shipmentLevelExecution)
            {
                shipmentLevelExecution = true;
            }

            if (!TMSTask && metCustTable.FinalizationDocument != METFinalizationDocument::None)
            {
                Info("@MET:ShipmentThreads");

                while select ShipmentId, OrderNum from metSalesOrderShipmentLoadLines
                    group by ShipmentId, OrderNum
                        where metSalesOrderShipmentLoadLines.ShipmentId == enumerator.current()
                {
                    postQueue.clear();
                    postQueue.ProcessId = this.topPickingProcessId;
                    postQueue.ShipmentId = metSalesOrderShipmentLoadLines.ShipmentId;
                    postQueue.SalesId = metSalesOrderShipmentLoadLines.OrderNum;
                    postQueue.ShipmentLevelExecute = shipmentLevelExecution;
                    shipmentConfirmationRecordList.add(postQueue);

                    shipmentLevelExecution = false;
                }
            }
            else
            {
                postQueue.clear();
                postQueue.ProcessId = this.topPickingProcessId;
                postQueue.ShipmentId = enumerator.current();
                postQueue.ShipmentLevelExecute = shipmentLevelExecution;

                shipmentConfirmationRecordList.add(postQueue);
            }

            ttscommit;

        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch 
        {
            exceptionTextFallThrough();
        }
    }
    shipmentConfirmationRecordList.insertDatabase();
}

/// <summary>
/// Waits for the task to finish.
/// </summary>
public void addDependentTask()
{
    if (!WHSParameters::find().METDisableTMSPostingDependentTask && isExecutingInBatch)
    {
        SysOperationServiceController controllerTMS;
        METSalesOrderShipmentConfirmationContract taskDataContract;

        taskDataContract = dataContract as METSalesOrderShipmentConfirmationContract;
        taskDataContract.parmTMS(true);

        // Re-initialize queue shipment specific. Since previous queue is already processed.
        this.processShipmentConfirmation(taskDataContract);
        taskDataContract.parmTopPickingProcessId(topPickingProcessId); // updating new topPickingProcessId

        con             = list2Con(taskDataContract.parmShipmentIdList());
        remaningCount   = taskDataContract.parmShipmentIdList().elements() mod taskDataContract.parmThreadCount();

        for (int i = 1; i <= threadCount; i++)
        {
            controllerTMS = new SysOperationServiceController(this.getTaskServiceClass(), this.getTaskServiceClassMethod());
            controllerTMS.parmDialogCaption(strFmt("TMS - %1",this.getTaskServiceCaption()));

            // grab contract instance from controller, use same contract
            taskDataContract = controllerTMS.getDataContractObject();
            this.initTaskDataContract(taskDataContract);
            taskDataContract.parmTMS(true);

            batchHeader.addRuntimeTask(controllerTMS, headerTaskId);

            SetEnumerator se = addedTasks.getEnumerator();

            while (se.moveNext())
            {
                batchHeader.addDependency(controllerTMS, se.current());
            }
        }

        batchHeader.save();
    }
    else
    {
        super();
    }
}
